function countClearWindows(s: string): number {
  const k = 3, cnt = new Array(26).fill(0);
  let dup = 0, count = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i) - 97;
    if (++cnt[c] === 2) dup++;
    if (i >= k) {
      const o = s.charCodeAt(i - k) - 97;
      if (cnt[o]-- === 2) dup--;
    }
    if (i >= k - 1 && dup === 0) count++;
  }
  return count;
}

