class Solution:
    def countClearWindows(self, s: str) -> int:
        k = 3
        cnt = [0] * 26
        dup = count = 0
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            cnt[c] += 1
            if cnt[c] == 2:
                dup += 1
            if i >= k:
                o = ord(s[i - k]) - 97
                if cnt[o] == 2:
                    dup -= 1
                cnt[o] -= 1
            if i >= k - 1 and dup == 0:
                count += 1
        return count

